use std::{hint::black_box, time::Instant};
fn old(data: &[u8]) -> [u8; 32] { use old_sha2::Digest; black_box(old_sha2::Sha256::digest(black_box(data))).into() }
fn new(data: &[u8]) -> [u8; 32] { use new_sha2::Digest; black_box(new_sha2::Sha256::digest(black_box(data))).into() }
fn main() {
    let data = vec![0xa5; 64 * 1024 * 1024];
    assert_eq!(old(&data),new(&data));
    for _ in 0..2 { black_box(old(&data)); black_box(new(&data)); }
    for sample in 0..6 {
        let order: [(&str,fn(&[u8])->[u8; 32]);2] = if sample % 2 == 0 { [("0.10.9-asm",old),("0.11.1-default",new)] } else { [("0.11.1-default",new),("0.10.9-asm",old)] };
        for (name,run) in order { let start=Instant::now(); for _ in 0..8 { black_box(run(&data)); } println!("{{\"version\":\"{name}\",\"sample\":{sample},\"bytes\":{},\"seconds\":{:.9}}}",data.len()*8,start.elapsed().as_secs_f64()); }
    }
}
